const retryAdaptiveOutbox = `-- name: RetryAdaptiveOutbox :execrows
UPDATE aura.adaptive_outbox
SET status = CASE
        WHEN attempts >= $1 THEN 'dead_letter'
        ELSE 'pending'
    END,
    available_at = $2,
    lease_owner = NULL,
    lease_expires_at = NULL,
    projected_at = NULL,
    dead_letter_at = CASE
        WHEN attempts >= $1 THEN $3::timestamptz
        ELSE NULL
    END,
    last_error_class = $4
WHERE id = $5
  AND status = 'leased'
  AND lease_owner = $6
`

type RetryAdaptiveOutboxParams struct {
	MaxAttempts int32              `json:"max_attempts"`
	AvailableAt pgtype.Timestamptz `json:"available_at"`
	FailedAt    pgtype.Timestamptz `json:"failed_at"`
	ErrorClass  pgtype.Text        `json:"error_class"`
	EventID     pgtype.UUID        `json:"event_id"`
	WorkerID    pgtype.Text        `json:"worker_id"`
}

func (q *Queries) RetryAdaptiveOutbox(ctx context.Context, arg RetryAdaptiveOutboxParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryAdaptiveOutbox,
		arg.MaxAttempts,
		arg.AvailableAt,
		arg.FailedAt,
		arg.ErrorClass,
		arg.EventID,
		arg.WorkerID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
